using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

class Program
{
    static void Main(string[] args)
    {
        var binlogPath = args[0];
        var build = BinaryLog.ReadBuild(binlogPath);

        Console.WriteLine("=== BUILD RESULT: " + (build.Succeeded ? "SUCCESS" : "FAILED") + " ===\n");

        // Collect all errors
        var errors = new List<(string project, string code, string message, string file, int line)>();
        build.VisitAllChildren<Error>(error => {
            var project = GetParentProject(error);
            errors.Add((project, error.Code ?? "", error.Message ?? "", error.File ?? "", error.LineNumber));
        });

        Console.WriteLine($"Total errors: {errors.Count}\n");

        // Group by project
        var byProject = errors.GroupBy(e => e.project).OrderBy(g => g.Key);
        foreach (var group in byProject)
        {
            Console.WriteLine($"--- Project: {group.Key} ---");
            foreach (var err in group)
            {
                Console.WriteLine($"  [{err.code}] {err.file}({err.line}): {err.message}");
            }
            Console.WriteLine();
        }

        // Also show warnings that might be relevant
        var warnings = new List<(string project, string code, string message)>();
        build.VisitAllChildren<Warning>(w => {
            var project = GetParentProject(w);
            if (w.Code == "NU1101" || w.Code == "NU1102" || w.Code == "MSB3245" || 
                w.Code == "CS8785" || (w.Code ?? "").StartsWith("NU"))
                warnings.Add((project, w.Code ?? "", w.Message ?? ""));
        });

        if (warnings.Any())
        {
            Console.WriteLine("=== RELEVANT WARNINGS ===");
            foreach (var w in warnings.Take(30))
            {
                Console.WriteLine($"  [{w.code}] ({w.project}): {w.message}");
            }
        }
    }

    static string GetParentProject(BaseNode node)
    {
        var current = node.Parent;
        while (current != null)
        {
            if (current is Project p)
                return System.IO.Path.GetFileName(p.ProjectFile ?? "unknown");
            if (current is Target t && t.Parent is Project tp)
                return System.IO.Path.GetFileName(tp.ProjectFile ?? "unknown");
            current = current.Parent;
        }
        return "unknown";
    }
}
