using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

class Program
{
    static void Main(string[] args)
    {
        var binlogPath = args[0];
        var build = BinaryLog.ReadBuild(binlogPath);

        // Find all projects and their dependencies
        Console.WriteLine("=== PROJECT STRUCTURE ===");
        var projects = new List<(string name, string file)>();
        build.VisitAllChildren<Project>(p => {
            projects.Add((p.Name ?? "", p.ProjectFile ?? ""));
        });
        foreach (var p in projects.Distinct())
        {
            Console.WriteLine($"  {p.name} -> {p.file}");
        }

        // Check for dependency-related messages
        Console.WriteLine("\n=== MSB3202 / PROJECT REFERENCE FAILURES ===");
        build.VisitAllChildren<Error>(error => {
            if ((error.Code ?? "").Contains("MSB3202") || (error.Code ?? "").Contains("MSB4019") || 
                (error.Text ?? "").Contains("could not be resolved"))
                Console.WriteLine($"  [{error.Code}] {error.Text}");
        });

        // Check PackageReferences
        Console.WriteLine("\n=== PACKAGE RESTORE INFO ===");
        build.VisitAllChildren<Warning>(w => {
            if ((w.Code ?? "").StartsWith("NU") || (w.Text ?? "").Contains("package"))
                Console.WriteLine($"  [{w.Code}] {w.Text}");
        });

        // Check if any projects failed
        Console.WriteLine("\n=== FAILED TARGETS ===");
        build.VisitAllChildren<Target>(t => {
            if (!t.Succeeded)
                Console.WriteLine($"  Target '{t.Name}' failed in {GetParentProject(t)}");
        });
    }

    static string GetParentProject(BaseNode node)
    {
        var current = node.Parent;
        while (current != null)
        {
            if (current is Project p)
                return System.IO.Path.GetFileName(p.ProjectFile ?? "unknown");
            current = current.Parent;
        }
        return "unknown";
    }
}
